const payload = $('WAHA Trigger').item.json.payload;
const contact = (payload._data && payload._data.key && payload._data.key.remoteJidAlt)
  ? payload._data.key.remoteJidAlt.split('@')[0]
  : String(payload.from || '').split('@')[0];

// The Redis node output key is media_buffer_state
const rawBuffer = String($input.item.json.media_buffer_state || '').trim();
let existing = [];
if (rawBuffer) {
  try { existing = JSON.parse(rawBuffer).files || []; } catch(e) { existing = []; }
}

const newFile = {
  url: (payload.media && payload.media.url) ? payload.media.url : '',
  filename: (payload.media && payload.media.filename) ? payload.media.filename : '',
  mimetype: (payload.media && payload.media.mimetype) ? payload.media.mimetype : ''
};

if (newFile.url) existing.push(newFile);

const pendingToken = contact + '_' + String(payload.timestamp || Date.now());
const state = {
  contact: contact,
  files: existing,
  pending_token: pendingToken,
  last_message_at: String(payload.timestamp || ''),
  session: $('WAHA Trigger').item.json.session || 'default'
};

return {
  json: {
    ...state,
    redis_key: 'media_buffer:' + contact,
    redis_value: JSON.stringify(state)
  }
};

let state = {};
try {
  state = JSON.parse(String($json.media_buffer_state || '{}'));
} catch(e) { state = {}; }

const files = state.files || [];
const contact = state.contact || '';
const session = state.session || 'default';

// Build a combined description of all files for supplier_message
const fileList = files.map((f, i) => `File ${i+1}: ${f.filename || 'unnamed'} (${f.mimetype || 'unknown'})`).join('\n');
const mergedMessage = files.length > 1
  ? `[Sent ${files.length} files]\n${fileList}`
  : (files.length === 1 ? `[Sent file: ${files[0].filename || 'unnamed'}]` : '');

return {
  json: {
    // Format compatible with Normalize WAHA Payload output
    'Контакты': contact,
    supplier_message: mergedMessage,
    has_media: files.length > 0,
    media_url: files[0] ? files[0].url : '',
    file_name: files[0] ? files[0].filename : '',
    mime_type: files[0] ? files[0].mimetype : '',
    // Extra field: all files for potential multi-upload
    all_files: JSON.stringify(files),
    files_count: files.length,
    session: session,
    redis_key: $('Build Media Buffer Update').item.json.redis_key
  }
};

// Support both text path (via Normalize WAHA Payload) and media buffer path (via Build Buffered Media Output)
let incoming;
try {
  incoming = $('Normalize WAHA Payload1').item.json;
  // Verify it has data
  if (!incoming || !incoming['Контакты']) throw new Error('empty');
} catch(e) {
  try {
    incoming = $('Build Buffered Media Output').item.json;
  } catch(e2) {
    incoming = {};
  }
}
const row = $json || {};
return {
  json: {
    contact: incoming['Контакты'],
    supplier_message: incoming.supplier_message,
    has_media: incoming.has_media,
    media_url: incoming.media_url || '',
    file_name: incoming.file_name || '',
    mime_type: incoming.mime_type || '',
    all_files: incoming.all_files || '',
    files_count: incoming.files_count || (incoming.has_media ? 1 : 0),
    session: incoming.session || 'default',
    current_stage: row['Stage'] || 'new',
    known_company_name: row['Название компании временно'] || '',
    known_activity: row['Деятельность компании временно'] || '',
    known_catalog: row['Ссылка на каталог временно'] || '',
    package_done: row['Полный пакет получен'] || '',
    first_contact_sent: row['First Contact Sent'] || '',
    status_chat: row['Статус'] || ''
  }
};

const incoming = $('Normalize Telegram payload1').item.json;
const raw = String($json.buffer_state || '').trim();
let row = {};
if (raw) {
  try {
    row = JSON.parse(raw);
  } catch (e) {
    row = {};
  }
}
const existingBuffer = String(row.Buffer || '').trim();
const currentPart = String(incoming.message_text || '').trim();
const mergedBuffer = [existingBuffer, currentPart].filter(Boolean).join(' ').replace(/\s+/g, ' ').trim();
const state = {
  'Chat ID': incoming.chat_id,
  'Buffer': mergedBuffer,
  'Pending Token': incoming.pending_token,
  'Last Message At': incoming.timestamp,
  'Sender Name': incoming.sender_name,
  'Username': incoming.username,
  'Last Reply': row['Last Reply'] || '',
  'Updated At': $now
};
return {
  json: {
    ...state,
    redis_key: `tg_buffer:${incoming.chat_id}`,
    redis_value: JSON.stringify(state)
  }
};

let row = {};
try {
  row = JSON.parse(String($json.buffer_state || '{}'));
} catch (e) {
  row = {};
}
return {
