    redis_key: $('Build buffer update1').item.json.redis_key
  }
};

const remoteJid = $('If4').first().json.payload._data.key.remoteJid || '';
const remoteJidAlt = $('If4').first().json.payload._data.key.remoteJidAlt || '';

const blacklist = $('Get row(s) in sheet').all()
  .map(item => item.json['Номер телефона'].toString().trim());

const isBlocked = blacklist.some(num => 
  remoteJid.includes(num) || 
  remoteJidAlt.includes(num) ||
  num.includes(remoteJid.replace('@lid', '').replace('@s.whatsapp.net', '')) ||
  num.includes(remoteJidAlt.replace('@lid', '').replace('@s.whatsapp.net', ''))
);

if (isBlocked) {
  return [];
}

return [$('If4').first()];

